import { $, api, esc, state, configList, loadCountryLaunches, loadCountryBlueprints, loadAdminCountries, loadProductCountries, countryPickerMarkup, bindCountryPicker, bindProductCountryPicker, loadCommandCenter, launchManifestFromForm, ensureStepUp, login, navigate, productEcosystemState } from './context.js';
import { refreshAdminData as refreshData } from './data.js';
async function loadExpansionCases(){const d=await api('/api/platform/admin/expansions?limit=100');return d.expansions||[]}
async function loadExpansionWorkspace(id){const d=await api(`/api/platform/admin/expansions/${id}`);return d.workspace||{}}
async function loadExpansionDefinitions(country='',sector=''){const q=new URLSearchParams();if(country)q.set('country',country);if(sector)q.set('sector',sector);q.set('limit','100');const d=await api(`/api/platform/admin/product-definitions?${q}`);return d.definitions||[]}
function expansionStatusPill(v){const x=String(v||'').toLowerCase();return `<span class="pill ${['live','ready','healthy','completed'].includes(x)?'ok':['blocked','failed','retired'].includes(x)?'bad':'warn'}">${esc(String(v||'—').toUpperCase())}</span>`}
function expansionTaskCard(t){const done=['completed','skipped','not_applicable'].includes(t.status);const manual=['decision','reuse','deltas'].includes(t.task_key);return `<article class="card stat"><div class="section-head"><div><span class="eyebrow">${esc(t.category)}</span><h3>${esc(t.title)}</h3></div>${expansionStatusPill(t.status)}</div><p class="sub">${esc(t.description)}</p><div class="mini">Authority: ${esc(t.authority)} · ${t.dependency_task_id?'Dependency required':'No dependency'}</div><div class="actions compact">${!done&&manual&&t.status!=='blocked'?`<button class="btn primary" data-exp-task="${esc(t.task_key)}">MARK COMPLETE</button>`:''}${!done&&!manual&&t.status!=='blocked'?`<span class="mini">Complete through the canonical action above; this task cannot be manually bypassed.</span>`:''}${t.status==='blocked'?`<span class="mini">Blocked by dependency or canonical authority.</span>`:''}</div></article>`}
async function renderExpansionWorkspace(){const box=$('#ecosystem-view-expansion') || $('#view-expansion');if(!box)return;box.innerHTML='<div class="empty">Loading Expansion Workspace…</div>';try{const [cases,countries,defs]=await Promise.all([loadExpansionCases(),Promise.resolve(state.data?.countries||[]),loadExpansionDefinitions()]);const defaultCase=cases[0]||null;box.innerHTML=`<div class="eyebrow">SUPER ADMIN · EXPANSION WORKSPACE</div><h1 class="title">Decide, prepare, compose, verify and launch a product</h1><p class="sub">One governed workspace orchestrates expansion. Canonical Country Foundation, Product Definition, Product Health, Verification and Launch services remain authoritative; Expansion only coordinates them.</p><section class="card section"><div class="section-head"><div><span class="eyebrow">STEP 1 · EXPANSION DECISION</span><h2>What do you want to expand?</h2><p class="sub">Choose the target market and the existing product to reuse. Creating an expansion case does not mutate the source.</p></div></div><form id="expansionCreateForm" class="form-grid">${countryPickerMarkup('ex-','Target country')}<label class="field">Target sector<input id="ex-Sector" class="input" value="general" placeholder="logistics"></label><label class="field">Expansion type<select id="ex-Type" class="input"><option value="new_country">New country</option><option value="new_sector">New sector</option><option value="new_language">New language</option><option value="capability">Capability expansion</option><option value="workflow">Workflow expansion</option><option value="variant">Product variant</option></select></label><label class="field">Source product<select id="ex-Source" class="input"><option value="">Select source product…</option>${defs.map(d=>`<option value="${d.id}">${esc(d.name)} · ${esc(d.country_code)} · ${esc(d.sector_code)} · v${esc(d.definition_version)}</option>`).join('')}</select></label><div class="actions full"><button class="btn primary" type="submit">START EXPANSION</button><span id="expCreateMsg" class="mini"></span></div></form></section><section class="card section"><div class="section-head"><div><span class="eyebrow">ACTIVE EXPANSIONS</span><h2>Expansion cases</h2></div></div><div class="table-wrap"><table class="table"><thead><tr><th>Target</th><th>Source</th><th>Type</th><th>Status</th><th>Stage</th><th>Progress</th><th>Open</th></tr></thead><tbody>${cases.map(c=>`<tr><td><b>${esc(c.target_country_code)}</b><div class="mini">${esc(c.target_sector_code)}</div></td><td>${esc(c.source_definition_id||'—')}</td><td>${esc(c.expansion_type)}</td><td>${expansionStatusPill(c.status)}</td><td>${esc(c.stage)}</td><td>${esc(c.progress??'—')}%</td><td><button class="btn muted" data-exp-open="${c.id}">OPEN WORKSPACE</button></td></tr>`).join('')||'<tr><td colspan="7" class="empty">No expansion cases yet.</td></tr>'}</tbody></table></div></section><section id="expansionWorkspaceDetail"></section>`;bindCountryPicker('ex-');$('#expansionCreateForm').onsubmit=async e=>{e.preventDefault();if(!await ensureStepUp())return;const code=$('#ex-CountryCode')?.value||'';const source=Number($('#ex-Source')?.value||0)||null;if(!code||!source){$('#expCreateMsg').textContent='Select a target country and source product.';return}$('#expCreateMsg').textContent='Creating governed expansion case…';try{const r=await api('/api/platform/admin/expansions',{method:'POST',body:JSON.stringify({targetCountryCode:code,targetSectorCode:$('#ex-Sector').value,expansionType:$('#ex-Type').value,sourceDefinitionId:source})});$('#expCreateMsg').textContent='Expansion case created.';await renderExpansionWorkspace();await renderExpansionDetail(Number(r.workspace?.case?.id))}catch(e){$('#expCreateMsg').textContent=e.message||'Expansion creation failed'}};document.querySelectorAll('[data-exp-open]').forEach(b=>b.onclick=()=>renderExpansionDetail(Number(b.dataset.expOpen)));if(defaultCase)await renderExpansionDetail(Number(defaultCase.id));}catch(e){box.innerHTML=`<section class="card section error-state"><div class="eyebrow">EXPANSION WORKSPACE ERROR</div><h2>The expansion workspace could not be loaded.</h2><div class="notice">${esc(e.message||'Expansion unavailable')}</div><button class="btn primary" data-exp-retry>RETRY</button></section>`;box.querySelector('[data-exp-retry]')?.addEventListener('click',()=>navigate('expansion'))}}
async function renderExpansionDetail(id){const host=$('#expansionWorkspaceDetail');if(!host||!id)return;host.innerHTML='<div class="empty">Loading expansion workspace…</div>';try{const w=await loadExpansionWorkspace(id),c=w.case||{},s=w.summary||{};const meta=c.metadata||{};const live=c.status==='live';host.innerHTML=`<section class="card section"><div class="section-head"><div><span class="eyebrow">EXPANSION WORKSPACE · ${esc(c.expansionKey)}</span><h2>${esc(c.targetCountryCode)} · ${esc(c.targetSectorCode)} ${live?'— LIVE PRODUCT':''}</h2><p class="sub">${live?'Expansion has become a live product. Future changes remain versioned and preserve lineage.':'From decision → plan → foundation → reuse + deltas → composition → compile → health → verification → launch → runtime.'}</p></div>${expansionStatusPill(c.status)}</div><div class="grid four"><article class="card stat"><span>Status</span><strong>${expansionStatusPill(c.status)}</strong><div class="mini">Stage: ${esc(c.stage)}</div></article><article class="card stat"><span>Health</span><strong>${expansionStatusPill(w.health?.status||'unknown')}</strong><div class="mini">${w.health?.blockers?.length||0} blockers · ${w.health?.warnings?.length||0} warnings</div></article><article class="card stat"><span>Progress</span><strong>${Number(s.progress||0)}%</strong><div class="mini">${Number(s.completed||0)} / ${Number(s.required||0)} required stages</div></article><article class="card stat"><span>Lineage</span><strong>${(w.lineage||[]).length}</strong><div class="mini">Source → target relationships</div></article></div></section><section class="grid two"><article class="card section"><div class="section-head"><div><span class="eyebrow">DECISION</span><h2>Target / Source / Scope / Owner</h2></div></div><div class="facts"><div class="fact"><span>Target</span><strong>${esc(c.targetCountryCode)} · ${esc(c.targetSectorCode)}</strong></div><div class="fact"><span>Source definition</span><strong>${esc(c.sourceDefinitionId||'—')}</strong></div><div class="fact"><span>Expansion type</span><strong>${esc(c.expansionType)}</strong></div><div class="fact"><span>Owner</span><strong>${esc(c.ownerType||'platform')}</strong></div></div></article><article class="card section"><div class="section-head"><div><span class="eyebrow">NEXT ACTION</span><h2>Do the next valid thing</h2></div></div><div class="notice">${(w.tasks||[]).find(t=>['ready','in_progress','blocked'].includes(t.status))?esc((w.tasks||[]).find(t=>['ready','in_progress','blocked'].includes(t.status)).title):live?'Product is live; review lineage for the next expansion.':'No actionable task is currently available.'}</div><div class="actions">${!meta.blueprintId?`<button class="btn primary" data-exp-foundation="${c.id}">PREPARE COUNTRY FOUNDATION</button>`:''}${meta.blueprintId&&!meta.definitionId?`<button class="btn primary" data-exp-compose="${c.id}">COMPOSE PRODUCT</button>`:''}${meta.definitionId&&!w.health?.definition?.compiledHash?`<button class="btn primary" data-exp-compile="${c.id}">COMPILE PRODUCT</button>`:''}${meta.launchId&&w.health?.definition?.compiledHash&&!w.launchWorkspace?.summary?.ready?`<button class="btn muted" data-exp-validate="${c.id}">VALIDATE LAUNCH</button>`:''}${meta.launchId&&w.launchWorkspace?.summary?.ready&&c.status!=='live'&&c.status!=='launching'?`<button class="btn primary" data-exp-activate="${c.id}">ACTIVATE PRODUCT</button>`:''}${c.status==='launching'&&(w.verification||[]).some(v=>v.status==='succeeded')?`<button class="btn primary" data-exp-finalize="${c.id}">FINALIZE LIVE PRODUCT</button>`:''}${meta.definitionId?`<button class="btn muted" data-exp-refresh="${c.id}">REFRESH CANONICAL HEALTH</button>`:''}</div></article></section><section class="card section"><div class="section-head"><div><span class="eyebrow">PLAN</span><h2>Generated dependency-aware plan</h2></div></div><div class="grid two">${(w.tasks||[]).map(expansionTaskCard).join('')}</div></section><section class="card section"><div class="section-head"><div><span class="eyebrow">REUSE + DELTAS</span><h2>Inherited · Modified · Added · Removed</h2><p class="sub">The source product is never mutated. Every target difference remains explicit.</p></div></div><div class="table-wrap"><table class="table"><thead><tr><th>Component</th><th>Change</th><th>Source</th><th>Target</th><th>Status</th></tr></thead><tbody>${(w.deltas||[]).map(d=>`<tr><td><b>${esc(d.component_type)}</b><div class="mini">${esc(d.component_key)}</div></td><td>${expansionStatusPill(d.change_type)}</td><td>${esc(d.source_ref||'—')}</td><td>${esc(d.target_ref||'—')}</td><td>${esc(d.status)}</td></tr>`).join('')||'<tr><td colspan="5" class="empty">No component deltas yet.</td></tr>'}</tbody></table></div></section><section class="grid two"><article class="card section"><div class="section-head"><div><span class="eyebrow">BLOCKERS</span><h2>Product Health</h2></div></div><div class="checks">${(w.health?.blockers||[]).map(productHealthIssue).join('')||'<div class="empty">No Product Health blockers.</div>'}</div></article><article class="card section"><div class="section-head"><div><span class="eyebrow">PRODUCT PREVIEW</span><h2>Governed target composition</h2></div></div><div class="notice"><b>${esc(c.targetCountryCode)} · ${esc(c.targetSectorCode)}</b><br>Definition #${esc(meta.definitionId||'—')} · Launch #${esc(meta.launchId||'—')}<br>Experience is rendered only through trusted declarative primitives.</div><div class="actions"><button class="btn muted" data-exp-preview>PREVIEW PRODUCT</button></div></article></section><section class="card section"><div class="section-head"><div><span class="eyebrow">EVIDENCE</span><h2>Foundation · Definition · Compilation · Verification · Launch</h2></div></div><div class="launch-contract"><article><b>Foundation</b><span>${meta.blueprintId?'Prepared':'Not prepared'}</span></article><article><b>Definition</b><span>${meta.definitionId?'Composed':'Not composed'}</span></article><article><b>Compilation</b><span>${w.health?.definition?.compiledHash?'Integrity hash present':'Not compiled'}</span></article><article><b>Verification</b><span>${(w.verification||[]).length?'Verification evidence recorded':'Not yet recorded'}</span></article><article><b>Launch</b><span>${w.launchWorkspace?.summary?.ready?'Preparation ready':c.status==='live'?'LIVE':'Not ready'}</span></article></div></section><section class="card section"><div class="section-head"><div><span class="eyebrow">CANONICAL PREPARATION</span><h2>Foundation and launch preparation</h2><p class="sub">These are the existing canonical Product Preparation tasks required by the launch authority. Expansion surfaces them here instead of creating a second preparation system.</p></div><span class="pill ${w.launchWorkspace?.summary?.ready?'ok':'warn'}">${w.launchWorkspace?`${Number(w.launchWorkspace.summary?.completed||0)} / ${Number(w.launchWorkspace.summary?.total||0)} READY ITEMS`:'NOT CREATED'}</span></div><div class="grid two">${(w.launchWorkspace?.tasks||[]).map(t=>`<article class="card stat"><div class="section-head"><div><b>${esc(t.title)}</b><div class="mini">${esc(t.category)} · ${t.required?'required':'optional'}</div></div>${expansionStatusPill(t.status)}</div><p class="sub">${esc(t.description)}</p>${t.status!=='completed'&&t.required?`<button class="btn muted" data-exp-prep-task="${t.id}">OPEN PREPARATION TASK</button>`:''}</article>`).join('')||'<div class="empty">Create the target launch version to generate canonical preparation tasks.</div>'}</div></section><section class="card section"><div class="section-head"><div><span class="eyebrow">PRODUCT LINEAGE</span><h2>Source → target history</h2></div></div><div class="lineage-tree">${(w.lineage||[]).map(l=>`<article><b>${esc(l.parent_definition_id||'Source')}</b><span> ${esc(l.relation)} → </span><b>${esc(l.child_definition_id||'Target')}</b></article>`).join('')||'<div class="empty">Lineage will appear when the target definition is composed.</div>'}</div></section><section class="card section"><div class="section-head"><div><span class="eyebrow">HISTORY</span><h2>Who changed what and when</h2></div></div><div class="table-wrap"><table class="table"><thead><tr><th>Stage</th><th>Status</th><th>Authority</th><th>Updated</th><th>Evidence</th></tr></thead><tbody>${(w.tasks||[]).filter(t=>t.status==='completed').map(t=>`<tr><td>${esc(t.title)}</td><td>${expansionStatusPill(t.status)}</td><td>${esc(t.authority)}</td><td>${esc(t.updated_at)}</td><td>${esc(t.completion_note||'—')}</td></tr>`).join('')||'<tr><td colspan="5" class="empty">No completed expansion stages yet.</td></tr>'}</tbody></table></div></section>${live?`<section class="card section"><div class="section-head"><div><span class="eyebrow">LIVE PRODUCT</span><h2>Health · Version · Dependencies · Country · Sector · Capabilities · Variants · Changes · Expansion history</h2></div><span class="pill ok">LIVE</span></div><p class="sub">This expansion is now a live product. Future expansion creates a new version or child lineage node; it does not mutate historical truth.</p></section>`:''}`;
document.querySelectorAll('[data-exp-task]').forEach(b=>b.onclick=async()=>{if(!await ensureStepUp())return;try{await api(`/api/platform/admin/expansions/${id}/tasks/${encodeURIComponent(b.dataset.expTask)}`,{method:'POST',body:JSON.stringify({status:'completed',note:'Completed from Expansion Workspace.',evidence:{actor:'super_admin'}})});await renderExpansionDetail(id)}catch(e){alert(e.message)}});host.querySelector('[data-exp-foundation]')?.addEventListener('click',async()=>{if(!await ensureStepUp())return;try{await api(`/api/platform/admin/expansions/${id}/foundation`,{method:'POST',body:JSON.stringify({})});await renderExpansionDetail(id)}catch(e){alert(e.message)}});host.querySelector('[data-exp-compose]')?.addEventListener('click',async()=>{if(!await ensureStepUp())return;try{await api(`/api/platform/admin/expansions/${id}/compose`,{method:'POST',body:'{}'});await renderExpansionDetail(id)}catch(e){alert(e.message)}});host.querySelector('[data-exp-compile]')?.addEventListener('click',async()=>{if(!await ensureStepUp())return;try{await api(`/api/platform/admin/expansions/${id}/compile`,{method:'POST',body:'{}'});await renderExpansionDetail(id)}catch(e){alert(e.message)}});host.querySelector('[data-exp-validate]')?.addEventListener('click',async()=>{if(!await ensureStepUp())return;try{await api(`/api/platform/admin/expansions/${id}/validate`,{method:'POST',body:'{}'});await renderExpansionDetail(id)}catch(e){alert(e.message)}});host.querySelector('[data-exp-activate]')?.addEventListener('click',async()=>{if(!await ensureStepUp())return;if(!confirm('Activate this product through the canonical launch authority?'))return;try{const launches=await loadCountryLaunches();const active=launches.find(x=>x.country_code===c.targetCountryCode&&x.active);await api(`/api/platform/admin/expansions/${id}/activate`,{method:'POST',body:JSON.stringify({expectedActiveLaunchId:active?.id??null,expectedActiveVersion:active?.version??null})});await renderExpansionDetail(id)}catch(e){alert(e.message)}});host.querySelector('[data-exp-finalize]')?.addEventListener('click',async()=>{if(!await ensureStepUp())return;try{await api(`/api/platform/admin/expansions/${id}/finalize`,{method:'POST',body:'{}'});await renderExpansionDetail(id)}catch(e){alert(e.message)}});host.querySelector('[data-exp-refresh]')?.addEventListener('click',()=>renderExpansionDetail(id));host.querySelectorAll('[data-exp-prep-task]').forEach(b=>b.onclick=()=>{if(meta.launchId){productStudioState.launchId=Number(meta.launchId);productStudioState.countryCode=c.targetCountryCode;navigate('product-studio');}});host.querySelector('[data-exp-preview]')?.addEventListener('click',()=>alert(`Governed preview: ${c.targetCountryCode} · ${c.targetSectorCode} · definition ${meta.definitionId||'not composed'}`));}catch(e){host.innerHTML=`<div class="empty">${esc(e.message||'Expansion workspace unavailable')}</div>`}}
async function loadProductHealth(country='',sector=''){const q=new URLSearchParams();if(country)q.set('country',country);if(sector)q.set('sector',sector);const d=await api(`/api/platform/admin/product-health${q.toString()?`?${q}`:''}`);return d.health||{};}
function productHealthPill(status){return `<span class="pill ${status==='healthy'?'ok':status==='blocked'?'bad':'warn'}">${esc(String(status||'UNKNOWN').toUpperCase())}</span>`}
function productHealthIssue(i){return `<article class="check"><div class="section-head"><div><b>${esc(i.code)}</b><div class="mini">${esc(i.stage||'platform')}</div></div>${productHealthPill(i.severity==='blocker'?'blocked':'warning')}</div><p class="sub">${esc(i.message)}</p>${i.details&&Object.keys(i.details).length?`<code>${esc(JSON.stringify(i.details))}</code>`:''}</article>`}
async function renderProductHealth(){
  const box=$('#view-product-health');if(!box)return;box.innerHTML='<div class="empty">Loading Product Health Engine…</div>';
  try{
    const countries=await loadProductCountries('',250,true);const sectors=state.data?.sectors||[];const defaultCountry=countries[0]?.code||'';
    box.innerHTML=`<div class="eyebrow">SUPER ADMIN · PRODUCT HEALTH</div><h1 class="title">Know exactly what blocks product creation</h1><p class="sub">Product Health follows the complete governed path from Super Admin access to a consumable running product. It reports blockers and broken dependencies; it does not replace canonical authorities.</p><section class="card section"><form id="productHealthForm" class="form-grid">${countryPickerMarkup('ph-','Country')}<label class="field">Sector<select id="productHealthSector" class="input"><option value="">All / inferred</option>${sectors.map(x=>`<option value="${esc(x.sector_code)}">${esc(x.sector_code)}</option>`).join('')}</select></label><div class="actions" style="align-items:end"><button class="btn primary" type="submit">CHECK PRODUCT PATH</button></div></form></section><section id="productHealthResult"></section>`;
    bindProductCountryPicker('ph-',{initialCode:defaultCountry,initialName:countries.find(c=>c.code===defaultCountry)?.name||''});$('#productHealthForm').onsubmit=async e=>{e.preventDefault();await runProductHealth()};
    await runProductHealth(defaultCountry,'');
  }catch(e){box.innerHTML=`<section class="card section error-state"><div class="eyebrow">PRODUCT HEALTH ERROR</div><h2>Health engine unavailable</h2><div class="notice">${esc(e.message||'Unable to evaluate product health')}</div></section>`}
}
async function runProductHealth(countryOverride=null,sectorOverride=null){
  const country=countryOverride!==null?(countryOverride||''):($('#ph-CountryCode')?.value||'');const sector=sectorOverride!==null?(sectorOverride||''):($('#productHealthSector')?.value||'');const host=$('#productHealthResult');if(!host)return;host.innerHTML='<div class="empty">Evaluating the governed product path…</div>';
  try{const h=await loadProductHealth(country,sector);host.innerHTML=`<section class="grid four"><article class="card stat"><span>Overall</span><strong>${productHealthPill(h.status)}</strong><div class="mini">Score ${Number(h.score||0)}%</div></article><article class="card stat"><span>Blockers</span><strong>${h.blockers?.length||0}</strong><div class="mini">Must resolve before the path is complete</div></article><article class="card stat"><span>Warnings</span><strong>${h.warnings?.length||0}</strong><div class="mini">Should be reviewed</div></article><article class="card stat"><span>Definition</span><strong>${esc(h.definition?.productKey||'—')}</strong><div class="mini">${h.definition?`v${esc(h.definition.version)} · ${esc(h.definition.status)}`:'Not selected'}</div></article></section><section class="card section"><div class="section-head"><div><span class="eyebrow">GOVERNED CREATION PATH</span><h2>Definition → Composition → Compile → Manifest → Experience → Health → Readiness → Activation → Verification → Runtime</h2></div>${productHealthPill(h.status)}</div><div class="grid four">${Object.entries(h.stages||{}).map(([k,v])=>`<article class="card stat"><span>${esc(k)}</span><strong>${productHealthPill(v.status)}</strong><div class="mini">${v.blockers||0} blockers · ${v.warnings||0} warnings</div></article>`).join('')}</div></section><section class="card section"><div class="section-head"><div><span class="eyebrow">BLOCKERS</span><h2>What must be fixed</h2></div></div><div class="checks">${(h.blockers||[]).map(productHealthIssue).join('')||'<div class="empty">No blocking issues found.</div>'}</div></section><section class="card section"><div class="section-head"><div><span class="eyebrow">WARNINGS</span><h2>What should be reviewed</h2></div></div><div class="checks">${(h.warnings||[]).map(productHealthIssue).join('')||'<div class="empty">No warnings.</div>'}</div></section>`}catch(e){host.innerHTML=`<div class="empty">${esc(e.message||'Product Health evaluation failed')}</div>`}
}

async function loadCommercial(){
  const d=await api('/api/platform/admin/subscriptions');
  return {plans:Array.isArray(d.plans)?d.plans:[],subscriptionStates:Array.isArray(d.subscriptionStates)?d.subscriptionStates:[]};
}
async function createCountryLaunchDraft(){
  if(!state.superAdmin){alert('Super Admin session required');return}
  const prefix=$('#pl-CountryCode')?'pl-':'pf-';const code=$(`#${prefix}CountryCode`)?.value;if(!code){const m=$('#countryLaunchMsg');if(m)m.textContent='Select a country first.';return}
  const msg=$('#countryLaunchMsg');msg.textContent='Preparing product draft…';
  try{
    const launch=await api('/api/platform/admin/country-product-launches/drafts',{method:'POST',body:JSON.stringify({countryCode:code,blueprintId:Number(document.querySelector(`#${prefix}Blueprint`)?.value||0)||null,manifest:launchManifestFromForm(prefix),reason:'Prepared in Super Admin Product Launch Center'})});
    const created=launch.launch||launch;msg.textContent=`Draft v${created.version||'—'} created. Opening the preparation workspace…`;await renderProductLaunch();const select=$('#launchWorkspaceSelect');if(select&&created.id){select.value=String(created.id);await renderProductLaunchWorkspace(Number(created.id))}
  }catch(e){msg.textContent=e.message||'Draft creation failed'}
}
async function countryLaunchAction(id,action){
  if(!state.superAdmin){alert('Super Admin session required');return}
  if(!await ensureStepUp())return;
  const verb={validate:'validate',activate:'activate',retire:'retire'}[action]||action;
  if(!confirm(`${verb.toUpperCase()} this country product version?`))return;
  try{const launches=await loadCountryLaunches();const target=launches.find(x=>Number(x.id)===Number(id));const active=target?launches.find(x=>x.country_code===target.country_code&&x.active):null;const body={};if(action==='activate'){body.expectedActiveLaunchId=active?.id??null;body.expectedActiveVersion=active?.version??null}await api(`/api/platform/admin/country-product-launches/${id}/${action}`,{method:'POST',body:JSON.stringify(body)});await refreshData();if(state.view==='product-launch')await renderProductLaunch();else await renderPlatformCenter()}catch(e){alert(e.message||'Country product action failed')}
}
async function loadLaunchWorkspace(id){const d=await api(`/api/platform/admin/country-product-launches/${id}/workspace`);return d.workspace||{};}
async function loadDependencyGraph(id){const d=await api(`/api/platform/admin/country-product-launches/${id}/dependency-graph`);return d.graph||{};}
async function updatePreparationTask(id,status){if(!state.superAdmin)return;if(status==='completed'&&!await ensureStepUp())return;const note=prompt(status==='completed'?'Completion note / evidence summary:':'Optional task note:','');if(note===null)return;let evidence={};if(status==='completed'){const sources=prompt('Source/evidence references (comma separated; required for source-controlled tasks):','');if(sources===null)return;evidence={sources:sources.split(',').map(x=>x.trim()).filter(Boolean)};}try{const r=await api(`/api/platform/admin/product-preparation/tasks/${id}`,{method:'PATCH',body:JSON.stringify({status,completionNote:note,evidence})});await renderProductLaunchWorkspace(Number($('#launchWorkspaceSelect')?.value||0),r.workspace)}catch(e){alert(e.message)}}
async function updatePreparationResearch(id){if(!state.superAdmin)return;if(!await ensureStepUp())return;const findings=prompt('Research findings — record the concrete requirement, decision or gap:','');if(findings===null)return;const sourceText=prompt('Source references (URLs, regulator pages, official documents, internal evidence):','');if(sourceText===null)return;try{const r=await api(`/api/platform/admin/product-preparation/research/${id}`,{method:'PATCH',body:JSON.stringify({status:'completed',findings,sources:sourceText.split(',').map(x=>x.trim()).filter(Boolean)})});await renderProductLaunchWorkspace(Number($('#launchWorkspaceSelect')?.value||0),r.workspace)}catch(e){alert(e.message)}}
async function addLaunchResearch(launchId){if(!await ensureStepUp())return;const topic=prompt('Research topic:','Country / sector requirement');if(topic===null)return;const question=prompt('Research question:','What requirement must be satisfied before launch?');if(question===null)return;try{await api(`/api/platform/admin/country-product-launches/${launchId}/workspace/research`,{method:'POST',body:JSON.stringify({topic,question})});await renderProductLaunchWorkspace(launchId)}catch(e){alert(e.message)}}
async function addLaunchTask(launchId){if(!await ensureStepUp())return;const title=prompt('Todo item title:','');if(!title)return;const description=prompt('What must be completed?','');if(description===null)return;try{await api(`/api/platform/admin/country-product-launches/${launchId}/workspace/tasks`,{method:'POST',body:JSON.stringify({title,description,category:'custom',required:true,sourceRequired:true})});await renderProductLaunchWorkspace(launchId)}catch(e){alert(e.message)}}
function lifecycleTemplate(sector){
  const code=String(sector||'general').toLowerCase();
  if(code==='logistics')return {name:'Logistics Lifecycle',initialStateCode:'PENDING',states:[['PENDING','Pending',false,false],['ARRIVED','Arrived',false,false],['PICKED_UP','Picked Up',false,true],['IN_TRANSIT','In Transit',false,true],['DELIVERED','Delivered',false,false],['COMPLETED','Completed',true,false],['CANCELLED','Cancelled',true,false]],transitions:[['PENDING','ARRIVED','ARRIVE','confirm_arrival',['admin','driver','executor']],['ARRIVED','PICKED_UP','PICKUP','confirm_pickup',['admin','driver','executor']],['PICKED_UP','IN_TRANSIT','TRANSIT_START','start_transit',['admin','driver','executor']],['IN_TRANSIT','DELIVERED','DELIVER','confirm_delivery',['admin','driver','executor']],['DELIVERED','COMPLETED','COMPLETE','complete_mission',['admin']],['PENDING','CANCELLED','CANCEL','cancel_mission',['admin']],['ARRIVED','CANCELLED','CANCEL_ARRIVED','cancel_mission',['admin']],['PICKED_UP','CANCELLED','CANCEL_PICKED_UP','cancel_mission',['admin']],['IN_TRANSIT','CANCELLED','CANCEL_IN_TRANSIT','cancel_mission',['admin']],['DELIVERED','CANCELLED','CANCEL_DELIVERED','cancel_mission',['admin']]],metadata:{domain:'logistics',supportsStops:true,supportsObjects:true,supportsCustody:true}};
  return {name:`${code.replaceAll('_',' ')} Lifecycle`,initialStateCode:'CREATED',states:[['CREATED','Created',false,false],['IN_PROGRESS','In Progress',false,false],['COMPLETED','Completed',true,false],['CANCELLED','Cancelled',true,false]],transitions:[['CREATED','IN_PROGRESS','START','start_work',['admin','operator']],['IN_PROGRESS','COMPLETED','COMPLETE','complete_work',['admin','operator']],['CREATED','CANCELLED','CANCEL','cancel_work',['admin']],['IN_PROGRESS','CANCELLED','CANCEL_IN_PROGRESS','cancel_work',['admin']]],metadata:{domain:code,supportsStops:false,supportsObjects:false,supportsCustody:false}};
}
function lifecyclePayloadFromJson(raw,sector){
  const x=JSON.parse(raw);const states=(x.states||[]).map((v,i)=>Array.isArray(v)?{stateCode:v[0],label:v[1],terminal:Boolean(v[2]),custodyActive:Boolean(v[3]),sequenceNo:(i+1)*10}:v);const transitions=(x.transitions||[]).map((v,i)=>Array.isArray(v)?{fromStateCode:v[0],toStateCode:v[1],transitionCode:v[2],actionCode:v[3]||null,requiredRoles:v[4]||[],sequenceNo:(i+1)*10}:v);return {...x,sectorCode:String(sector||x.sectorCode||'general').toLowerCase(),states,transitions};
}
async function loadLifecycleHealth(launchId){return (await api(`/api/platform/admin/country-product-launches/${launchId}/lifecycle-health`)).health||{sectors:[]};}
async function renderLaunchLifecyclePanel(launch){
  const sectors=[...new Set((launch.eligibility?.sectors||['general']).map(x=>String(x).trim().toLowerCase()).filter(Boolean))];
  let health={sectors:[]};try{health=await loadLifecycleHealth(launch.id)}catch(e){health={sectors:sectors.map(sectorCode=>({sectorCode,configured:false,valid:false,error:e.message}))};}
  const cards=[];
  for(const sector of sectors){
    const h=health.sectors?.find(x=>x.sectorCode===sector)||{sectorCode:sector,configured:false,valid:false};
    let definitions=[];try{definitions=await (await api(`/api/platform/admin/lifecycles?country=${encodeURIComponent(launch.country_code)}&sector=${encodeURIComponent(sector)}`)).lifecycles||[]}catch{}
    const active=definitions.find(x=>x.id===h.lifecycleDefinitionId)||definitions.find(x=>x.status==='active')||definitions[0];
    const template=lifecycleTemplate(sector);const value=JSON.stringify(active?{name:active.name,sectorCode:active.sectorCode,initialStateCode:active.initialStateCode,states:active.states.map(x=>({stateCode:x.stateCode,label:x.label,terminal:x.terminal,custodyActive:x.custodyActive,sequenceNo:x.sequenceNo})),transitions:active.transitions.map(x=>({fromStateCode:x.fromStateCode,toStateCode:x.toStateCode,transitionCode:x.transitionCode,actionCode:x.actionCode,requiredRoles:x.requiredRoles,sequenceNo:x.sequenceNo})),livenessPolicy:active.livenessPolicy,metadata:active.metadata}:template,null,2);
    cards.push(`<article class="card section lifecycle-contract" data-lifecycle-sector="${esc(sector)}"><div class="section-head"><div><span class="eyebrow">SECTOR LIFECYCLE · ${esc(sector.toUpperCase())}</span><h3>${esc(active?.name||template.name)}</h3><p class="sub">${h.valid?'Active lifecycle contract is bound to this launch.':'No valid lifecycle is bound. Product launch cannot safely become operational until this contract is configured.'}</p></div><span class="pill ${h.valid?'ok':'warn'}">${h.valid?'ACTIVE':'REQUIRED'}</span></div><div class="grid three"><article class="card stat"><span>States</span><strong>${active?.states?.length||template.states.length}</strong><div class="mini">Sector-defined lifecycle</div></article><article class="card stat"><span>Transitions</span><strong>${active?.transitions?.length||template.transitions.length}</strong><div class="mini">Server-enforced</div></article><article class="card stat"><span>Domain</span><strong>${sector==='logistics'?'STOPS + OBJECTS':'SECTOR CONTRACT'}</strong><div class="mini">Canonical operational model</div></article></div><label class="field full" style="margin-top:12px">Lifecycle contract JSON<textarea class="input" rows="14" data-lifecycle-json="${esc(sector)}">${esc(value)}</textarea></label><div class="actions"><button class="btn primary" data-lifecycle-save="${esc(sector)}">SAVE & VALIDATE</button>${h.lifecycleDefinitionId?`<button class="btn muted" data-lifecycle-activate="${esc(sector)}" data-lifecycle-id="${Number(h.lifecycleDefinitionId)}">BIND / ACTIVATE</button>`:''}<span class="mini" data-lifecycle-msg="${esc(sector)}">${h.error?esc(h.error):h.valid?'Bound and ready.':'Define, validate and bind this sector contract.'}</span></div></article>`);
  }
  return `<section class="card section"><div class="section-head"><div><span class="eyebrow">PRODUCT CONTRACT · SECTOR LIFECYCLES</span><h2>Define the lifecycle before launch</h2><p class="sub">Lifecycle is a product/sector contract. Super Admin defines it here; the Canonical Core enforces the selected contract at runtime. Logistics receives Stops, Objects, Custody and Evidence semantics; other sectors supply their own operational lifecycle.</p></div><span class="pill ${health.sectors?.length&&health.sectors.every(x=>x.valid)?'ok':'warn'}">${health.sectors?.length&&health.sectors.every(x=>x.valid)?'ALL SECTORS READY':'LIFECYCLE REQUIRED'}</span></div>${cards.join('')}</section>`;
}
async function bindLaunchLifecyclePanel(launch){
  document.querySelectorAll('[data-lifecycle-save]').forEach(btn=>btn.onclick=async()=>{if(!await ensureStepUp())return;const sector=btn.dataset.lifecycleSave;const msg=document.querySelector(`[data-lifecycle-msg="${CSS.escape(sector)}"]`);try{msg.textContent='Saving lifecycle contract…';const payload=lifecyclePayloadFromJson(document.querySelector(`[data-lifecycle-json="${CSS.escape(sector)}"]`).value,sector);const current=await api(`/api/platform/admin/lifecycles?country=${encodeURIComponent(launch.country_code)}&sector=${encodeURIComponent(sector)}`);const existing=(current.lifecycles||[]).find(x=>x.status==='active')||(current.lifecycles||[])[0];const created=await api('/api/platform/admin/lifecycles',{method:'POST',body:{...payload,countryCode:launch.country_code,launchId:Number(launch.id),lifecycleDefinitionId:existing?.id||null}});const validated=await api(`/api/platform/admin/lifecycles/${created.lifecycle.id}/validate`,{method:'POST'});await api(`/api/platform/admin/country-product-launches/${launch.id}/sectors/${encodeURIComponent(sector)}/lifecycle`,{method:'POST',body:{lifecycleDefinitionId:validated.lifecycle.id,productDefinitionId:null}});msg.textContent='Lifecycle validated and bound to this product sector.';await renderProductLaunchWorkspace(launch.id)}catch(e){msg.textContent=e.message||'Lifecycle update failed'}});
  document.querySelectorAll('[data-lifecycle-activate]').forEach(btn=>btn.onclick=async()=>{if(!await ensureStepUp())return;const sector=btn.dataset.lifecycleActivate;const msg=document.querySelector(`[data-lifecycle-msg="${CSS.escape(sector)}"]`);try{msg.textContent='Binding lifecycle…';await api(`/api/platform/admin/country-product-launches/${launch.id}/sectors/${encodeURIComponent(sector)}/lifecycle`,{method:'POST',body:{lifecycleDefinitionId:Number(btn.dataset.lifecycleId)}});msg.textContent='Lifecycle bound.';await renderProductLaunchWorkspace(launch.id)}catch(e){msg.textContent=e.message||'Lifecycle binding failed'}});
}

async function renderProductLaunchWorkspace(launchId,workspace=null){const host=$('#launchWorkspace');if(!host)return;if(!launchId){host.innerHTML='<div class="empty">Create or select a country product draft to open its launch workspace.</div>';return}try{const launches=await loadCountryLaunches();const launch=launches.find(x=>Number(x.id)===Number(launchId));if(!launch){host.innerHTML='<div class="empty">Launch not found.</div>';return}const w=workspace||await loadLaunchWorkspace(launchId);const g=await loadDependencyGraph(launchId).catch(e=>({summary:{nodes:0,edges:0,blockedNodes:0,ready:false},edges:[],error:e.message||'Dependency graph unavailable'}));const groups={};(w.tasks||[]).forEach(t=>(groups[t.category]??=[]).push(t));host.innerHTML=`<section class="card section"><div class="section-head"><div><span class="eyebrow">PRODUCT WORKSPACE · ${esc(launch.country_code)}</span><h2>${esc(launch.country_name)} → ${(launch.eligibility?.sectors||['general']).map(esc).join(', ')}</h2><p class="sub">Version ${esc(launch.version)} · ${esc(launch.status)} · ${Number(w.summary?.progress||0)}% of required preparation complete</p></div><span class="pill ${w.summary?.ready?'ok':'warn'}">${w.summary?.ready?'READY FOR VALIDATION':'PREPARATION INCOMPLETE'}</span></div><div class="grid four"><article class="card stat"><span>Todo progress</span><strong>${Number(w.summary?.progress||0)}%</strong><div class="mini">${Number(w.summary?.completed||0)} / ${Number(w.summary?.total||0)} required tasks</div></article><article class="card stat"><span>Remaining</span><strong>${Number(w.summary?.remaining||0)}</strong><div class="mini">Required pieces not complete</div></article><article class="card stat"><span>Research</span><strong>${Number(w.summary?.researchCompleted||0)} / ${Number(w.summary?.researchTotal||0)}</strong><div class="mini">Evidence-backed research</div></article><article class="card stat"><span>Dependency graph</span><strong>${Number(g.summary?.nodes||0)}</strong><div class="mini">${Number(g.summary?.edges||0)} relationships</div></article></div><div class="notice" style="margin-top:14px"><b>Next action:</b> ${w.summary?.ready?(launch.status==='draft'?'Validate the prepared product.':launch.status==='validated'?'Activate the validated product.':'Review product verification and health.'):`Complete ${Number(w.summary?.remaining||0)} required preparation items and ${Number(w.summary?.researchTotal||0)-Number(w.summary?.researchCompleted||0)} research items.`}</div><div class="actions"><button class="btn muted" id="addLaunchResearch">ADD RESEARCH ITEM</button><button class="btn muted" id="addLaunchTask">ADD TODO ITEM</button>${launch.status==='draft'?(w.summary?.ready?`<button class="btn primary" data-launch-validate="${launch.id}">VALIDATE PRODUCT</button>`:`<button class="btn muted" disabled>COMPLETE ${Number(w.summary?.remaining||0)} REQUIRED ITEMS</button>`):''}${launch.status==='validated'?`<button class="btn primary" data-launch-activate="${launch.id}">ACTIVATE PRODUCT</button>`:''}</div></section>${launch.status==='draft'?`<section class="card section"><div class="section-head"><div><span class="eyebrow">DRAFT MANAGEMENT</span><h2>Edit the incomplete product before validation</h2><p class="sub">Draft edits remain private and are committed through the Governed Data Entry Gate. Country identity is immutable; product scope and presentation inputs remain editable until validation.</p></div><span class="pill warn">DRAFT</span></div><form id="launchDraftEditForm" class="form-grid"><label class="field">Sector(s)<input id="lde-Sectors" class="input" value="${esc((launch.eligibility?.sectors||['general']).join(','))}"></label><label class="field">Capabilities<input id="lde-Capabilities" class="input" value="${esc((launch.manifest?.capabilities||[]).join(','))}"></label><label class="field full">Required configurations<input id="lde-RequiredConfigs" class="input" value="${esc((launch.manifest?.requiredConfigurations||[]).join(','))}"></label><label class="field">Organization types<input id="lde-OrgTypes" class="input" value="${esc((launch.eligibility?.organizationTypes||['company']).join(','))}"></label><label class="field">User classes<input id="lde-UserClasses" class="input" value="${esc((launch.eligibility?.userClasses||[]).join(','))}"></label><label class="field full">Launch message<textarea id="lde-LaunchMessage" class="input">${esc(launch.manifest?.launchMessage||'ON Mission is available for this country.')}</textarea></label><div class="actions full"><button class="btn primary" type="submit">SAVE DRAFT THROUGH DATA ENTRY</button><button type="button" class="btn danger" id="deleteLaunchDraft">MOVE DRAFT TO TRASH</button><span id="launchDraftEditMsg" class="mini"></span></div></form></section>`:''}<section class="card section"><div class="section-head"><div><span class="eyebrow">RESEARCH FIRST</span><h2>Country + sector requirements</h2><p class="sub">Research is recorded with findings and sources. It becomes launch evidence; the platform does not invent legal requirements.</p></div></div><div class="table-wrap"><table class="table"><thead><tr><th>Topic</th><th>Question</th><th>Status</th><th>Finding</th><th>Action</th></tr></thead><tbody>${(w.research||[]).map(r=>`<tr><td><b>${esc(r.topic)}</b></td><td>${esc(r.question)}</td><td><span class="pill ${r.status==='completed'?'ok':r.status==='deferred'?'bad':'warn'}">${esc(r.status)}</span></td><td>${esc(r.findings||'—')}</td><td>${r.status!=='completed'?`<button class="btn muted" data-research-complete="${r.id}">COMPLETE RESEARCH</button>`:'<span class="mini">Evidence recorded</span>'}</td></tr>`).join('')||'<tr><td colspan="5" class="empty">No research items.</td></tr>'}</tbody></table></div></section><section class="card section"><div class="section-head"><div><span class="eyebrow">LAUNCH CHECKLIST</span><h2>Complete the small pieces</h2><p class="sub">Every required piece is visible. Complete the pieces, then the product moves toward validation automatically.</p></div></div>${Object.entries(groups).map(([cat,items])=>`<div class="launch-check-group"><h3>${esc(cat.replaceAll('_',' '))}</h3>${items.map(t=>`<article class="launch-check ${t.status==='completed'?'ready':t.status==='blocked'?'blocked':''}"><div><strong>${t.status==='completed'?'✓':t.status==='blocked'?'!':'○'} ${esc(t.title)}</strong><span>${esc(t.description)}</span>${t.completion_note?`<small>${esc(t.completion_note)}</small>`:''}</div><div class="check-actions">${t.status!=='completed'?`<button class="btn muted" data-task-status="${t.id}:in_progress">START</button><button class="btn primary" data-task-status="${t.id}:completed">COMPLETE</button>`:'<span class="pill ok">DONE</span>'}</div></article>`).join('')}</div>`).join('')}</section>${await renderLaunchLifecyclePanel(launch)}<section class="card section"><div class="section-head"><div><span class="eyebrow">DEPENDENCY GRAPH</span><h2>Why is this blocked?</h2><p class="sub">The graph connects product → country → sector → capability → configuration → policy → subscription → billing → verification → journey → user impact.</p></div></div><div class="table-wrap"><table class="table"><thead><tr><th>From</th><th>Relationship</th><th>To</th><th>Impact</th><th>Rollback</th></tr></thead><tbody>${(g.edges||[]).map(e=>`<tr><td><b>${esc(e.from_label)}</b><div class="mini">${esc(e.from_node_type)}</div></td><td><span class="pill ${e.relation==='blocks'?'warn':'ok'}">${esc(e.relation)}</span></td><td><b>${esc(e.to_label)}</b><div class="mini">${esc(e.to_node_type)}</div></td><td>${esc(JSON.stringify(e.impact||{}))}</td><td>${esc(JSON.stringify(e.rollback||{}))}</td></tr>`).join('')||'<tr><td colspan="5" class="empty">No dependency relationships yet.</td></tr>'}</tbody></table></div><div class="notice" style="margin-top:14px"><b>Blocked nodes:</b> ${Number(g.summary?.blockedNodes||0)} · <b>Graph state:</b> ${g.error?`Dependency graph unavailable: ${esc(g.error)}. Preparation and validation remain available.`:g.summary?.ready?'All required preparation dependencies satisfied':'One or more dependencies still require action.'}</div></section>`;$('#addLaunchResearch').onclick=()=>addLaunchResearch(launchId);$('#addLaunchTask').onclick=()=>addLaunchTask(launchId);$('#launchDraftEditForm')?.addEventListener('submit',async e=>{e.preventDefault();if(!await ensureStepUp())return;const msg=$('#launchDraftEditMsg');msg.textContent='Saving governed draft…';const csv=id=>String($(id)?.value||'').split(',').map(x=>x.trim()).filter(Boolean);try{const current=launch.manifest||{};const manifest={...current,capabilities:csv('#lde-Capabilities'),requiredConfigurations:csv('#lde-RequiredConfigs'),eligibility:{...(current.eligibility||{}),organizationTypes:csv('#lde-OrgTypes'),sectors:csv('#lde-Sectors'),userClasses:csv('#lde-UserClasses')},launchMessage:$('#lde-LaunchMessage')?.value||''};await api(`/api/platform/admin/country-product-launches/${launch.id}/draft`,{method:'PATCH',body:{countryCode:launch.country_code,blueprintId:launch.country_blueprint_id||null,manifest,reason:'Draft edited from Product Launch Workspace'}});msg.textContent='Draft saved through Data Entry Gate.';await renderProductLaunch()}catch(e){msg.textContent=e.message||'Draft save failed'}});$('#deleteLaunchDraft')?.addEventListener('click',async()=>{if(!await ensureStepUp())return;if(!confirm(`Move draft ${launch.country_code} v${launch.version} to Trash?`))return;try{await api('/api/platform/admin/trash',{method:'POST',body:{resourceType:'country_product_launch',resourceId:String(launch.id),reasonCode:'draft_cleanup',candidateReason:'Incomplete product draft removed by Super Admin'}});await renderProductLaunch()}catch(e){alert(e.message)}});document.querySelectorAll('[data-research-complete]').forEach(b=>b.onclick=()=>updatePreparationResearch(Number(b.dataset.researchComplete)));document.querySelectorAll('[data-task-status]').forEach(b=>{const [id,status]=b.dataset.taskStatus.split(':');b.onclick=()=>updatePreparationTask(Number(id),status)});document.querySelectorAll('[data-launch-validate]').forEach(b=>b.onclick=()=>countryLaunchAction(b.dataset.launchValidate,'validate'));document.querySelectorAll('[data-launch-activate]').forEach(b=>b.onclick=()=>countryLaunchAction(b.dataset.launchActivate,'activate'));await bindLaunchLifecyclePanel(launch)}catch(e){host.innerHTML=`<div class="empty">${esc(e.message||'Product Launch Workspace unavailable')}</div>`}}
async function renderProductLaunch(){const box=$('#view-product-launch');if(!box)return;box.innerHTML='<div class="empty">Loading Product Launch Operating System…</div>';try{const launches=await loadCountryLaunches();const countries=await loadProductCountries('',250,true);const sectors=state.data?.sectors||[];box.innerHTML=`<div class="eyebrow">SUPER ADMIN · PRODUCT LAUNCH OPERATING SYSTEM</div><h1 class="title">Build the product one small piece at a time</h1><p class="sub">Choose a country + sector, research what is required, turn the findings into a checklist, complete every required piece, understand dependencies, validate, launch, and then verify.</p><section class="card section logistics-domain-card"><div class="section-head"><div><span class="eyebrow">CANONICAL DOMAIN CONTRACT</span><h2>Logistics runs on the shared core</h2><p class="sub">Mission, assignment, executor, object, custody, evidence and action remain canonical. This product layer configures the sector; it does not create a second operational authority.</p></div><span class="pill ok">CANONICAL</span></div><div class="logistics-domain-flow"><span>MISSION</span><i>→</i><span>ASSIGNMENT</span><i>→</i><span>EXECUTOR</span><i>→</i><span>OBJECT</span><i>→</i><span>CUSTODY</span><i>→</i><span>EVIDENCE</span><i>→</i><span>ACTION</span></div></section><section class="grid four"><article class="card stat"><span>Products</span><strong>${launches.length}</strong><div class="mini">Draft, validated, active and retired versions</div></article><article class="card stat"><span>Active</span><strong>${launches.filter(x=>x.status==='active').length}</strong><div class="mini">Governed country products</div></article><article class="card stat"><span>Drafts</span><strong>${launches.filter(x=>x.status==='draft').length}</strong><div class="mini">Products still being prepared</div></article><article class="card stat"><span>Goal</span><strong>100%</strong><div class="mini">Preparation → validation → launch</div></article></section><section class="card section"><div class="section-head"><div><span class="eyebrow">STEP 1 · CHOOSE MARKET</span><h2>Start a country product</h2><p class="sub">This creates a governed draft and automatically creates the launch workspace, research questions and checklist.</p></div></div><form id="productLaunchStartForm" class="form-grid">${countryPickerMarkup('pl-','Country')}<label class="field">Prepared country blueprint<select id="pl-Blueprint" class="input"><option value="">Select prepared blueprint…</option></select></label><label class="field">Sector(s)<select id="pl-Sectors" class="input" required>${sectors.map(x=>`<option value="${esc(x.sector_code)}">${esc(x.sector_code)}</option>`).join('')}</select></label><label class="field">Capabilities<input id="pl-Capabilities" class="input" value="organization,people,mission,object,resource,relationship,communication,evidence,policy,capability,logistics"></label><label class="field full">Required configuration keys<input id="pl-RequiredConfigs" class="input" value="capabilities:catalog,roles:action_policy,rendering:product_experience,guidance:user_journey,policy:default,mission_rules:intake"></label><label class="field">Organization types<input id="pl-OrgTypes" class="input" value="company"></label><label class="field">User classes <span class="mini">canonical: tenant admin · executor · independent executor</span><input id="pl-UserClasses" class="input" value="tenant_admin,driver,independent_executor"></label><label class="field full">Launch message<textarea id="pl-LaunchMessage" class="input">ON Mission is available for this country.</textarea></label><div class="actions full"><button class="btn primary" type="submit">CREATE PRODUCT WORKSPACE</button><span id="countryLaunchMsg" class="mini">The workspace will show every remaining piece.</span></div></form></section><section class="card section"><div class="section-head"><div><span class="eyebrow">STEP 2 · WORKSPACE</span><h2>What needs to be done?</h2></div><select id="launchWorkspaceSelect" class="input" style="max-width:420px"><option value="">Select product…</option>${launches.map(x=>`<option value="${x.id}">${esc(x.country_name)} · v${esc(x.version)} · ${esc(x.status)}</option>`).join('')}</select></div><div id="launchWorkspace"><div class="empty">Select a product to see its research, checklist and dependency graph.</div></div></section><section class="card section"><div class="section-head"><div><span class="eyebrow">STEP 3 · GOVERNED VERSIONS</span><h2>Launch lifecycle</h2></div></div><div class="table-wrap"><table class="table"><thead><tr><th>Country</th><th>Version</th><th>Status</th><th>Sector</th><th>Readiness</th><th>Action</th></tr></thead><tbody>${launches.map(x=>`<tr><td><b>${esc(x.country_name)}</b><div class="mini">${esc(x.country_code)}</div></td><td>${esc(x.version)}</td><td><span class="pill ${x.status==='active'||x.status==='validated'?'ok':x.status==='draft'?'warn':'bad'}">${esc(x.status)}</span></td><td>${esc((x.eligibility?.sectors||[]).join(', ')||'—')}</td><td>${x.readiness?.valid===true?'<span class="pill ok">READY</span>':`<span class="pill warn">${Number(x.readiness?.score||0)}%</span>`}</td><td><div class="actions">${x.status==='draft'?`<button class="btn primary" data-launch-open="${x.id}">OPEN / EDIT</button><button class="btn danger" data-launch-trash="${x.id}">DELETE DRAFT</button>`:''}${x.status==='validated'?`<button class="btn primary" data-launch-open="${x.id}">OPEN & ACTIVATE</button>`:''}${x.status==='active'?`<button class="btn muted" data-launch-open="${x.id}">OPEN</button>`:''}${x.status==='retired'?`<button class="btn muted" data-launch-open="${x.id}">OPEN HISTORY</button>`:''}</div></td></tr>`).join('')||'<tr><td colspan="6" class="empty">No product workspaces yet.</td></tr>'}</tbody></table></div></section>`;$('#productLaunchStartForm').onsubmit=async e=>{e.preventDefault();await createCountryLaunchDraft()};$('#launchWorkspaceSelect').onchange=()=>renderProductLaunchWorkspace(Number($('#launchWorkspaceSelect').value||0));document.querySelectorAll('[data-launch-open]').forEach(b=>b.onclick=()=>{$('#launchWorkspaceSelect').value=b.dataset.launchOpen;renderProductLaunchWorkspace(Number(b.dataset.launchOpen))});document.querySelectorAll('[data-launch-trash]').forEach(b=>b.onclick=async()=>{if(!await ensureStepUp())return;if(!confirm('Move this incomplete product draft to Trash?'))return;try{await api('/api/platform/admin/trash',{method:'POST',body:{resourceType:'country_product_launch',resourceId:b.dataset.launchTrash,reasonCode:'draft_cleanup',candidateReason:'Incomplete product draft removed from Product Launch'}});await renderProductLaunch()}catch(e){alert(e.message)}});bindProductCountryPicker('pl-');const bp=await loadCountryBlueprints();const bs=$('#pl-Blueprint');if(bs)bs.innerHTML='<option value="">Select prepared blueprint…</option>'+bp.map(b=>`<option value="${b.id}">${esc(b.country_name)} · ${esc(b.status)} · ${esc(b.default_language_code)}</option>`).join('');const refreshBlueprints=()=>{const code=$('#pl-CountryCode')?.value||'';const eligible=bp.filter(b=>!code||b.country_code===code);if(bs)bs.innerHTML='<option value="">Select prepared blueprint…</option>'+eligible.map(b=>`<option value="${b.id}">${esc(b.country_name)} · ${esc(b.status)} · ${esc(b.default_language_code)}</option>`).join('')};refreshBlueprints();$('#pl-CountrySearch')?.addEventListener('country-selected',refreshBlueprints);bs?.addEventListener('change',async()=>{if(!bs.value)return;try{const r=await api(`/api/platform/admin/country-product-blueprints/${bs.value}`),b=r.blueprint;const sectorSelect=$('#pl-Sectors');if(sectorSelect){const sectors=(b.sectors||[]).filter(x=>x.status==='ready');sectorSelect.innerHTML=(sectors.length?sectors:b.sectors||[]).map(x=>`<option value="${esc(x.sector_code)}">${esc(x.sector_name||x.sector_code)}</option>`).join('')}const input=$('#pl-CountrySearch');if(input&&b.country_code!==$('#pl-CountryCode')?.value){$('#pl-CountryCode').value=b.country_code;input.value=`${b.country_name} (${b.country_code})`;refreshBlueprints()}}catch(e){alert(e.message)}});}catch(e){box.innerHTML=`<div class="empty">${esc(e.message||'Product Launch Operating System unavailable')}</div>`}}

async function renderLaunchReadiness(country,sector){const box=$('#launchReadiness');if(!box)return;box.innerHTML='<div class="empty">Evaluating canonical product readiness…</div>';try{const x=await loadCommandCenter({countryCode:country,sectorCode:sector});const l=x.productLens||{},r=l.readiness||{};box.innerHTML=`<div class="grid stats"><article class="card stat"><span>Availability</span><strong>${esc(l.availability||'—')}</strong><div class="mini">${esc(l.launchStatus||'—')}</div></article><article class="card stat"><span>Readiness score</span><strong>${Number(r.score||0)}%</strong><div class="mini">${r.valid===true?'No launch blockers':'Resolve blockers below'}</div></article><article class="card stat"><span>Product state</span><strong>${esc(l.productState||'—')}</strong><div class="mini">${esc(l.result||'—')}</div></article></div><section class="card section"><h3>Readiness contract</h3><div class="launch-gate">${Object.entries(r.checks||{}).map(([k,v])=>`<article class="${v?'ready':''}"><strong>${v?'✓':'!'} ${esc(k)}</strong><span>${v?'Satisfied':((r.blockers||[]).find(b=>b.code===k)?.message||'Attention required')}</span></article>`).join('')}</div>${(r.blockers||[]).length?`<div class="notice" style="margin-top:12px"><b>Blockers:</b> ${(r.blockers||[]).map(b=>esc(b.message)).join(' · ')}</div>`:'<div class="notice" style="margin-top:12px"><b>Result:</b> This scope satisfies the canonical launch readiness contract.</div>'}</section>`}catch(e){box.innerHTML=`<div class="empty">${esc(e.message||'Readiness unavailable')}</div>`}}

async function renderSubscriptions(){const box=$('#view-subscriptions');box.innerHTML='<div class="empty">Loading subscription authority…</div>';const d=await loadCommercial();const configs=configList().filter(x=>x&&x.domain_code==='subscription_plans');box.innerHTML=`<div class="eyebrow">COMMERCIAL PRODUCT</div><h1 class="title">Subscriptions</h1><p class="sub">Plans are configured through the existing versioned Platform Configuration Center. Runtime subscription state and entitlements remain authoritative here.</p><div class="grid stats"><article class="card stat"><span>Active plans</span><strong>${d.plans.length}</strong></article><article class="card stat"><span>Subscription states</span><strong>${d.subscriptionStates.length}</strong></article><article class="card stat"><span>Configured plan versions</span><strong>${configs.length}</strong></article><article class="card stat"><span>Entitlement authority</span><strong>CANONICAL</strong></article></div><section class="card section"><div class="section-head"><div><h2>Plan authority</h2><p class="sub">Price, currency, interval, capability set, limits and eligibility are product configuration—not authorization.</p></div><button class="btn muted" id="subscriptionConfig">OPEN CONFIGURATION CENTER</button></div><div class="table-wrap"><table class="table"><thead><tr><th>Plan</th><th>Price</th><th>Interval</th><th>Capabilities</th><th>Eligibility</th><th>Stripe</th></tr></thead><tbody>${d.plans.map(p=>`<tr><td><b>${esc(p.name)}</b><div class=mini>${esc(p.code)} · v${esc(p.version)}</div></td><td>${esc(p.currency)} ${(Number(p.price_minor||0)/100).toFixed(2)}</td><td>${esc(p.billing_interval)}</td><td>${esc(Object.keys(JSON.parse(p.capabilities_json||'{}')).filter(k=>JSON.parse(p.capabilities_json||'{}')[k]).join(', ')||'—')}</td><td>${esc(p.eligible_countries_json||'*')}</td><td>${p.stripe_price_id?'<span class="pill ok">CONFIGURED</span>':'<span class="pill warn">PENDING</span>'}</td></tr>`).join('')||'<tr><td colspan=6 class=empty>No plans configured.</td></tr>'}</tbody></table></div></section><section class="card section"><h2>Subscription state</h2><div class="grid three">${d.subscriptionStates.map(x=>`<article class="card stat"><span>${esc(x.status)}</span><strong>${Number(x.count||0)}</strong></article>`).join('')||'<div class=empty>No subscriptions yet.</div>'}</div></section>`;$('#subscriptionConfig').onclick=()=>navigate('data-entry')}
async function renderBilling(){const box=$('#view-billing');box.innerHTML='<div class="empty">Loading billing authority…</div>';const d=await loadCommercial();box.innerHTML=`<div class="eyebrow">BILLING</div><h1 class="title">Billing</h1><p class="sub">Financial state is provider-reconciled and organization-scoped. Billing never becomes the authorization engine.</p><div class="grid three"><article class="card section"><h2>Billing Identity</h2><p class=sub>Organization billing identity, country, currency and tax configuration.</p></article><article class="card section"><h2>Provider</h2><p class=sub>Stripe remains behind the canonical external-provider governance boundary.</p></article><article class="card section"><h2>Reconciliation</h2><p class=sub>Webhook events are idempotent and durable; provider truth is reconciled into canonical subscription state.</p></article></div><section class="card section"><h2>Commercial state</h2><div class="table-wrap"><table class="table"><thead><tr><th>Status</th><th>Organizations</th></tr></thead><tbody>${d.subscriptionStates.map(x=>`<tr><td><span class="pill ${['active','trialing'].includes(x.status)?'ok':['past_due','unpaid'].includes(x.status)?'warn':'bad'}">${esc(x.status)}</span></td><td>${Number(x.count||0)}</td></tr>`).join('')||'<tr><td colspan=2 class=empty>No billing state recorded.</td></tr>'}</tbody></table></div></section><section class="card section"><h2>Configuration</h2><p class=sub>Currency, tax configuration and invoice requirements are resolved from jurisdiction policy. Payment credentials and provider secrets remain infrastructure/provider configuration, never product configuration.</p><button class="btn muted" id="billingConfig">OPEN PLAN CONFIGURATION</button></section>`;$('#billingConfig').onclick=()=>navigate('subscriptions')}

async function renderSecurity(){
 const box=$('#view-security'); if(!box)return; box.innerHTML='<div class="workspace-loading"><span class="loading-dot"></span><div><b>Loading security posture</b><small>Reading live runtime controls and canonical configuration.</small></div></div>';
 try{
  const [health]=await Promise.all([api('/api/platform/admin/system-health')]);
  const checks=health?.certification?.checks||[];
  const degraded=health?.degradedAuthorities||[];
  const configs=configList().filter(x=>x?.domain_code==='operational_thresholds');
  const status=degraded.length?'REVIEW':String(health?.certification?.status||health?.currentSituation?.state||'UNKNOWN').toUpperCase();
  const tone=status==='CERTIFIED'||status==='HEALTHY'||status==='PROTECTED'?'ok':status==='REVIEW'||status==='WARNING'||status==='DEGRADED'?'warn':'bad';
  box.innerHTML=`<div class="eyebrow">SECURITY · OPERATIONAL POSTURE</div><div class="section-head"><div><h1 class="title">Security</h1><p class="sub">Live security posture plus versioned operational controls. This workspace observes canonical security state; it does not replace authentication, authorization or runtime enforcement.</p></div><div class="actions"><span class="pill ${tone}">${esc(status)}</span><button class="btn primary" id="refreshSecurity">REFRESH</button></div></div><section class="grid four"><article class="card stat"><span>Database</span><strong>${esc(health?.database?.status||'UNKNOWN')}</strong><div class="mini">Canonical data access</div></article><article class="card stat"><span>Authentication</span><strong>${esc(health?.authentication?.status||'UNKNOWN')}</strong><div class="mini">Session boundary</div></article><article class="card stat"><span>API</span><strong>${esc(health?.api?.status||'UNKNOWN')}</strong><div class="mini">Protected runtime</div></article><article class="card stat"><span>Certification</span><strong>${esc(health?.certification?.status||'UNKNOWN')}</strong><div class="mini">End-to-end evidence</div></article></section>${degraded.length?`<section class="card section authority-card"><div class="section-head"><div><span class="eyebrow">AUTHORITY AVAILABILITY</span><h2>Security posture requires review</h2><p class="sub">No unavailable authority is interpreted as healthy.</p></div><span class="pill bad">${degraded.length} UNAVAILABLE</span></div><div class="authority-list">${degraded.map(x=>`<div><b>${esc(x.authority||'Authority')}</b><span>${esc(x.code||'AUTHORITY_UNAVAILABLE')}</span></div>`).join('')}</div></section>`:''}<section class="card section"><div class="section-head"><div><span class="eyebrow">RUNTIME CONTROLS</span><h2>Operational configuration</h2><p class="sub">Configuration is evidence and policy input only; runtime authorities continue to enforce security.</p></div><span class="pill neutral">${configs.length} CONFIG</span></div>${configs.length?configTable(configs):'<div class="empty">No operational threshold configuration is currently projected.</div>'}</section><section class="card section"><div class="section-head"><div><span class="eyebrow">CERTIFICATION CHECKS</span><h2>Current proof chain</h2></div></div><div class="grid four">${checks.map(x=>`<article class="card stat"><span>${esc(x.key||'Check')}</span><strong>${esc(String(x.status||'UNKNOWN').toUpperCase())}</strong><div class="mini">${esc(x.detail||'')}</div></article>`).join('')||'<div class="empty">No certification checks returned.</div>'}</div></section>`;
  $('#refreshSecurity').onclick=()=>renderSecurity();
 }catch(e){box.innerHTML=`<section class="card section error-state"><div class="eyebrow">SECURITY AUTHORITY ERROR</div><h2>Security posture could not be loaded.</h2><p class="sub">No secure state is inferred from an unavailable authority.</p><div class="notice">${esc(e.message||'Security authority unavailable')}</div><button class="btn primary" id="retrySecurity">RETRY</button></section>`;$('#retrySecurity').onclick=()=>renderSecurity();}
}

function renderConfigDomain(domain,title,desc){const configs=configList().filter(x=>x && x.domain_code===domain);$('#view-'+({capabilities:'capabilities',mission_rules:'missions',subscription_plans:'subscriptions',limits:'billing',operational_thresholds:'security'}[domain]||domain)).innerHTML=`<div class="eyebrow">PLATFORM CONTROL</div><h1 class="title">${esc(title)}</h1><p class="sub">${esc(desc)}</p><section class="card section"><div class="notice">Configuration is versioned and governed. It never becomes a replacement for Authorization, Mission Truth, Billing state, or other canonical runtime authorities.</div></section><section class="card section">${configTable(configs)}</section>`}

async function createConfigDraft(){if(!state.superAdmin){$('#platformConfigMsg').textContent='Super Admin session required';return}const domain=prompt('Configuration domain (for example capabilities):','capabilities');if(domain===null)return;const key=prompt('Configuration key:','default');if(key===null)return;const raw=prompt('Configuration JSON payload:','{}');if(raw===null)return;let payload;try{payload=JSON.parse(raw)}catch{alert('Invalid JSON');return}try{await api('/api/platform/admin/platform-configurations/drafts',{method:'POST',body:JSON.stringify({domainCode:domain,configKey:key,version:'auto',payload,reason:'Platform configuration change'})});await refreshData();renderPlatformCenter()}catch(e){alert(e.message)}}
async function loadSystemHealth(){
  const box=$('#view-system-health');if(!box)return;
  box.innerHTML='<div class="empty">Reading current platform situation…</div>';
  try{
    const d=await api('/api/platform/admin/system-health');
    const s=d.currentSituation||{},c=d.currentData||{},providers=d.providers||{},billing=d.billing||{},backup=d.backup||{},cert=d.certification||{};
    const degraded=(d.degradedAuthorities||[]);
    const authorityNotice=degraded.length?`<div class="notice" style="margin-bottom:12px"><b>Some administrative authorities are unavailable.</b> ${esc(degraded.map(x=>x.authority||'authority').join(' · '))}. The view remains available and does not infer missing state.</div>`:'';
    box.innerHTML=authorityNotice+`<div class="eyebrow">SYSTEM HEALTH · LIVE SNAPSHOT</div>
    <div class="section-head"><div><h1 class="title">System Health</h1><p class="sub">Current platform state and governed operational data. This surface exposes aggregate metadata only; tenant payloads and private content remain outside the System Health view.</p></div><button class="btn primary" id="refreshSystemHealth">↻ REFRESH</button></div>
    <section class="grid four">
      <article class="card stat"><span>Current situation</span><strong>${esc(String(s.state||'UNKNOWN'))}</strong><div class="mini">${esc(s.reason||'Current platform state is being evaluated.')}</div></article>
      <article class="card stat"><span>Product</span><strong>${esc(s.productStatus||'UNKNOWN')}</strong><div class="mini">${esc(s.productReason||'No product status available.')}</div></article>
      <article class="card stat"><span>Release</span><strong>${esc(d.release||'—')}</strong><div class="mini">Evaluated ${esc(d.evaluatedAt||'—')}</div></article>
      <article class="card stat"><span>Next valid step</span><strong>${esc(s.nextAction||'Observe')}</strong><div class="mini">Derived from current canonical platform state</div></article>
    </section>
    <section class="card section"><div class="section-head"><div><span class="eyebrow">CURRENT DATA</span><h2>What is happening now</h2><p class="sub">These are live aggregate counts from the current database state, not cached release metadata.</p></div></div>
      <div class="grid four">
        <article class="card stat"><span>Organizations</span><strong>${Number(c.organizations||0)}</strong><div class="mini">Active records</div></article>
        <article class="card stat"><span>Active executors</span><strong>${Number(c.activeDrivers||0)}</strong><div class="mini">Operational profiles</div></article>
        <article class="card stat"><span>Open missions</span><strong>${Number(c.openMissions||0)}</strong><div class="mini">Non-terminal missions</div></article>
        <article class="card stat"><span>Active products</span><strong>${Number(c.activeCountryProducts||0)}</strong><div class="mini">Country product launches</div></article>
        <article class="card stat"><span>Pending data entry</span><strong>${Number(c.pendingDataEntries||0)}</strong><div class="mini">Preview / validated entries</div></article>
        <article class="card stat"><span>In Trash</span><strong>${Number(c.trashedRecords||0)}</strong><div class="mini">Reversible quarantine</div></article>
        <article class="card stat"><span>Open admin operations</span><strong>${Number(c.openAdministrativeOperations||0)}</strong><div class="mini">Preparing / executing / verifying</div></article>
        <article class="card stat"><span>Active providers</span><strong>${Number(providers.activeProviders||0)}</strong><div class="mini">Governed external providers</div></article>
      </div>
    </section>
    <section class="grid two">
      <article class="card section"><div class="section-head"><div><span class="eyebrow">RUNNING PRODUCT SURFACE</span><h2>Active country products</h2></div></div>
        <div class="checks">${(d.activeProducts||[]).map(x=>`<article class="check"><div class="section-head"><div><b>${esc(x.countryCode||'—')} · v${esc(x.version||'—')}</b><div class="mini">Launch #${esc(x.id)} · ${esc(x.status)}</div></div><span class="pill ok">ACTIVE</span></div><p class="sub">Sectors: ${esc((x.sectors||[]).join(', ')||'general / inferred')} · Updated ${esc(x.updatedAt||'—')}</p></article>`).join('')||'<div class="empty">No active country product is currently exposed.</div>'}</div>
      </article>
      <article class="card section"><div class="section-head"><div><span class="eyebrow">PLATFORM HEALTH</span><h2>Runtime services</h2></div></div>
        <div class="grid two"><article class="card stat"><span>Database</span><strong>${esc(d.database?.status||'UNKNOWN')}</strong></article><article class="card stat"><span>API</span><strong>${esc(d.api?.status||'UNKNOWN')}</strong></article><article class="card stat"><span>Authentication</span><strong>${esc(d.authentication?.status||'UNKNOWN')}</strong></article><article class="card stat"><span>Billing</span><strong>${esc(billing.status||'UNKNOWN')}</strong></article><article class="card stat"><span>Backup</span><strong>${esc(backup.status||'UNKNOWN')}</strong></article><article class="card stat"><span>Architecture</span><strong>${esc(d.releaseGate?.status||'UNKNOWN')}</strong><div class="mini">Baseline ${esc(d.releaseGate?.baseline||'—')}</div></article></div>
      </article>
    </section>
    <section class="card section"><div class="section-head"><div><span class="eyebrow">END-TO-END CERTIFICATION</span><h2>${esc(cert.status||'UNKNOWN').toUpperCase()}</h2><p class="sub">Admin · Product · Data · Mission lifecycle certification. No new authority is introduced.</p></div><span class="pill ${cert.status==='certified'?'ok':cert.status==='warning'?'warn':'bad'}">${esc(cert.status||'UNKNOWN')}</span></div><div class="grid four">${(cert.checks||[]).map(x=>`<article class="card stat"><span>${esc(x.key)}</span><strong>${esc(x.status).toUpperCase()}</strong><div class="mini">${esc(x.detail)}</div></article>`).join('')}</div></section><section class="card section"><div class="section-head"><div><span class="eyebrow">RECENT ADMINISTRATIVE TRUTH</span><h2>Latest governed activity</h2></div></div><div class="notice">${d.latestAdministrativeActivity?`<b>${esc(d.latestAdministrativeActivity.action||'Activity')}</b> · ${esc(d.latestAdministrativeActivity.resourceType||'resource')} #${esc(d.latestAdministrativeActivity.resourceId||'—')} · ${esc(d.latestAdministrativeActivity.createdAt||'—')}`:'No administrative activity recorded yet.'}</div></section>`;
    $('#refreshSystemHealth').onclick=()=>loadSystemHealth();
  }catch(e){box.innerHTML=`<div class="empty">${esc(e.message||'System Health unavailable')}</div>`}
}
async function refreshConfigurationAction(id,action){if(['validate','authorize','activate','rollback'].includes(action)&&!await ensureStepUp())return;try{let body={};if(action==='activate'){const c=configList().find(x=>Number(x.id)===Number(id));const current=configList().find(x=>x.domain_code===c?.domain_code&&x.config_key===c?.config_key&&x.active);body={expectedActiveConfigId:current?.id??null,expectedActiveVersion:current?.version??null}}await api(`/api/platform/admin/platform-configurations/${id}/${action}`,{method:'POST',body:JSON.stringify(body)});await refreshData();renderPlatformCenter()}catch(e){alert(e.message)}}


export { loadExpansionWorkspace, renderExpansionWorkspace, loadProductHealth, renderProductHealth, loadCommercial, createCountryLaunchDraft, countryLaunchAction, loadLaunchWorkspace, loadDependencyGraph, renderProductLaunch, renderSubscriptions, renderBilling, renderSecurity, renderConfigDomain, createConfigDraft, loadSystemHealth, refreshConfigurationAction };
